changeSet.sql:
INSERT INTO permissions (id, created_at, created_by, deleted, code, description) VALUES (gen_random_uuid(), now(), 'system', false, 'client.checkout.reserve', 'Reserve a plot and open a purchase transaction against it.'), (gen_random_uuid(), now(), 'system', false, 'client.kyc.manage', 'Submit and read one''s own purchase-time identity verification.'), (gen_random_uuid(), now(), 'system', false, 'admin.kyc.review', 'Read and decide buyers'' purchase-time identity verification.');
INSERT INTO role_permissions (id, created_at, created_by, deleted, role_id, permission_id) SELECT gen_random_uuid(), now(), 'system', false, r.id, p.id FROM roles r, permissions p WHERE r.code = 'buyer' AND p.code IN ('client.checkout.reserve', 'client.kyc.manage');
INSERT INTO role_permissions (id, created_at, created_by, deleted, role_id, permission_id) SELECT gen_random_uuid(), now(), 'system', false, r.id, p.id FROM roles r, permissions p WHERE r.code IN ('super_admin', 'compliance_officer') AND p.code = 'admin.kyc.review';

changeSet.rollback:
DELETE FROM role_permissions WHERE permission_id IN (
    SELECT id FROM permissions
     WHERE code IN ('client.checkout.reserve', 'client.kyc.manage', 'admin.kyc.review')
);
DELETE FROM permissions
 WHERE code IN ('client.checkout.reserve', 'client.kyc.manage', 'admin.kyc.review');
